'use strict';
/* Unified Case workspace; icons and original sample artwork live in ui-assets.js. */
const runStates={running:['运行中','blue','clock'],waiting:['等待操作','amber','pause'],passed:['通过','green','check'],failed:['未通过','red','alert'],stopped:['已停止','','stop']};
const stepStates={pending:['待执行','','clock'],sent:['动作已发送','blue','arrow'],verified:['结果已验证','green','check'],failed:['验证未通过','red','alert'],recovered:['重试后恢复','green','refresh'],insufficient:['证据不足','amber','info']};
const badge=(state,kind='run')=>{const s=(kind==='run'?runStates:stepStates)[state]||['尚未执行','','clock'];return `<span class="badge ${s[1]}">${icon(s[2])}${s[0]}</span>`;};
const dateTime=t=>new Date(t).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).replaceAll('/','-');
const clock=t=>new Date(t).toLocaleTimeString('zh-CN',{hour12:false});
const duration=n=>`${String(Math.floor(Math.max(0,n)/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,n))%60).padStart(2,'0')}`;
const ongoing=r=>r&&['running','waiting'].includes(r.status);
const tag=t=>`<span class="tag">${esc(t)}</span>`;
const options=(items,selected)=>items.map(v=>`<option ${v===selected?'selected':''}>${esc(v)}</option>`).join('');
let offline=!navigator.onLine;
let list={view:'all',search:'',module:'全部 Case',tag:'',owner:'',archive:'active',sort:'updated',controlled:false,scroll:0};
try{list={...list,...JSON.parse(sessionStorage.getItem('artemis-list-context')||'{}')};}catch{}
let screen={kind:'list'},workspaceStates=new Map(),menuId=null,toastTimer=null,playTimer=null,dialogReturn=null,modalKind='',modalContext={},unsavedEdit=false,deviceRefreshing=false;
let newCase={name:'',objective:'',description:'',module:'账号与登录',tags:[]};
try{newCase={...newCase,...JSON.parse(sessionStorage.getItem('artemis-new-draft')||'{}')};}catch{}
const editable=c=>c&&c.owner==='我'&&!c.control;
const getCase=()=>screen.kind==='workspace'?A.getCase(screen.caseId):null;
const currentRun=()=>screen.runId?A.getRun(screen.runId):null;
function viewState(){const key=screen.kind==='new'?'new':screen.caseId+':'+(screen.runId||'pending');if(!workspaceStates.has(key))workspaceStates.set(key,{input:screen.kind==='new'?newCase.objective:'',scroll:null,following:true,unread:0,rightTab:'live',pinned:false,selected:null,selectedVersion:'latest',replay:0,playing:false,connected:!offline,lastFrame:null,lastAt:null,descriptionOpen:false});return workspaceStates.get(key);}
function persistList(){try{sessionStorage.setItem('artemis-list-context',JSON.stringify(list));}catch{}}
function save(){if(!A.save())toast('浏览器存储不可用，修改仅保留在当前页面。');}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4300);}
function rememberView(){if(screen.kind==='list'){list.scroll=window.scrollY;persistList();}else{const el=$('#message-scroll');if(el){const s=viewState();s.scroll=el.scrollTop;s.input=$('#composer-input')?.value||s.input;}}}
function go(route){if(unsavedEdit){confirmDialog('离开编辑？','未保存的修改将被放弃。','放弃修改',()=>{unsavedEdit=false;closeDialog();go(route);});return;}rememberView();closeMenu();closeDialog();stopReplay();if(location.hash==='#/'+route)render();else location.hash='/'+route;}
function resolveRoute(){const p=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean);if(p[0]==='new'){history.replaceState(null,'','#/cases');return {kind:'list',create:true};}if(p[0]==='run'){const r=A.getRun(p[1]);if(r){history.replaceState(null,'',`#/case/${r.caseId}/run/${r.id}`);return {kind:'workspace',caseId:r.caseId,runId:r.id};}return {kind:'missing'};}if(p[0]==='case'){const c=A.getCase(p[1]);if(!c)return {kind:'missing'};let r=p[2]==='run'?A.getRun(p[3]):null;if(r&&r.caseId!==c.id)return {kind:'missing'};if(p[2]==='run'&&!r)return {kind:'missing'};if(!r&&(p[2]!=='pending'||!c.pending))r=c.pending?null:A.active(c.id)||A.runsFor(c.id)[0];return {kind:'workspace',caseId:c.id,runId:r?.id||null,edit:p[2]==='edit'};}return {kind:'list'};}
function render(){screen=resolveRoute();document.body.classList.toggle('in-workspace',['workspace','new'].includes(screen.kind));if(screen.kind==='list'){renderList();requestAnimationFrame(()=>window.scrollTo(0,list.scroll));if(screen.create)editCase(null);}else if(['workspace','new'].includes(screen.kind)){renderWorkspace();window.scrollTo(0,0);if(screen.edit)editCase(getCase());}else $('#app').innerHTML=`<main class="missing"><h1>找不到这条记录</h1><p>返回 Cases 查看当前工作区内容。</p>${btn('返回 Cases','back-list','','back')}</main>`;document.title=(getCase()?.name||'Cases')+' · Artemis';}
function filteredCases(){let rows=A.data.cases.filter(c=>(list.module==='全部 Case'||c.module===list.module)&&(list.archive==='all'||(list.archive==='archived'?c.archived:!c.archived))&&(list.view!=='mine'||c.owner==='我')&&(!list.owner||c.owner===list.owner)&&(!list.tag||c.tags.includes(list.tag))&&(!list.controlled||c.control));const q=list.search.trim().toLowerCase();if(q)rows=rows.filter(c=>[c.name,c.id,c.objective,...c.tags].join(' ').toLowerCase().includes(q));rows.sort(list.sort==='name'?(a,b)=>a.name.localeCompare(b.name,'zh-CN'):(a,b)=>b.updated-a.updated);return list.view==='recent'?rows.slice(0,8):rows;}
function renderList(){const rows=filteredCases();$('#app').innerHTML=`<header class="list-header"><div class="od-row brand">${logo()}<span>ARTEMIS</span><span class="workspace-label">测试工作区</span></div><div class="od-row"><span class="small muted">HappyCoding</span>${btn('设置','settings','','settings')}${ibtn('help','help','查看原型说明')}<span class="avatar">QA</span></div></header><main class="list-page"><div class="page-title"><div><div class="eyebrow">TEST CASES</div><h1>Cases</h1><p>用自然语言描述测试，在工作区里持续执行与观察。</p></div>${btn('新建 Case','new','primary','plus')}</div><div class="library-layout"><aside class="modules" aria-label="功能分类"><div class="section-label">功能模块</div>${['全部 Case',...A.modules].map(m=>`<button class="module ${list.module===m?'selected':''}" data-action="module" data-value="${m}">${icon(m==='全部 Case'?'grid':'folder')}<span>${m}</span><span class="count">${A.data.cases.filter(c=>!c.archived&&(m==='全部 Case'||c.module===m)).length}</span></button>`).join('')}</aside><section class="case-library"><div class="list-tabs"><nav class="tabs" aria-label="Case 范围">${[['all','全部'],['recent','最近更新'],['mine','我创建的']].map(([v,t])=>`<button class="tab ${v===list.view?'active':''}" data-action="list-view" data-value="${v}">${t}</button>`).join('')}</nav><span class="small muted" id="case-count">${rows.length} 个 Case</span></div><div class="toolbar"><label class="search-box" for="case-search">${icon('search')}<span class="sr-only">搜索 Case</span><input id="case-search" type="search" value="${esc(list.search)}" placeholder="搜索名称、目标或编号"><span class="shortcut">/</span></label><label class="filter"><span>标签</span><select id="tag-filter">${options(['全部','冒烟','回归','核心路径','网络','权限'],list.tag||'全部')}</select></label><label class="filter"><span>创建人</span><select id="owner-filter">${options(['全部','我','陈悦','林远'],list.owner||'全部')}</select></label><label class="filter"><span class="sr-only">归档筛选</span><select id="archive-filter"><option value="active" ${list.archive==='active'?'selected':''}>未归档</option><option value="archived" ${list.archive==='archived'?'selected':''}>已归档</option><option value="all" ${list.archive==='all'?'selected':''}>全部状态</option></select></label>${ibtn('settings','list-settings','更多筛选与排序')}</div>${list.archive==='archived'?'<p class="archive-hint">已从常用列表收起，定义和历史仍保留；可在行尾菜单中恢复。</p>':''}<div id="case-rows">${renderRows(rows)}</div><div class="list-footer"><span>点击 Case，直接进入工作区</span><span>运行状态仅代表最近一次执行</span></div></section></div></main><div id="row-menu" class="row-menu" hidden></div>`;}
function renderRows(rows){if(!rows.length)return `<div class="empty">${icon('search')}<h2>没有匹配的 Case</h2><p>调整关键词或筛选条件后重试。</p>${btn('清除筛选','clear-filters')}</div>`;return `<table class="case-table"><thead><tr><th class="case-name-col">Case</th><th class="module-col">分类</th><th class="latest-col">最近运行</th><th class="owner-col">创建人</th><th class="updated-col">最近更新</th><th class="more-col"><span class="sr-only">更多操作</span></th></tr></thead><tbody>${rows.map(c=>{const r=A.runsFor(c.id)[0];return `<tr data-open-case="${c.id}"><td><a class="case-name" href="#/case/${c.id}">${esc(c.name)}</a><div class="case-sub"><span class="mono">${c.id}</span>${c.tags.map(tag).join('')}${c.archived?tag('已归档'):''}${c.control?tag('控制中'):''}</div></td><td class="module-col">${esc(c.module)}</td><td class="latest-col"><div class="od-field">${r?badge(r.status):c.pending?'<span class="badge amber">待选设备</span>':'<span class="muted">尚未执行</span>'}${r?`<span class="mono small muted">${r.id}</span>`:''}</div></td><td class="owner-col"><span class="od-row"><span class="avatar ${c.owner==='我'?'me':''}">${c.owner==='我'?'QA':esc(c.owner.slice(-1))}</span>${esc(c.owner)}</span></td><td class="updated-col"><span class="small muted">${dateTime(c.updated)}</span></td><td>${ibtn('more','row-menu','更多 Case 操作',`data-id="${c.id}" aria-haspopup="menu" aria-expanded="false"`)}</td></tr>`;}).join('')}</tbody></table>`;}
function updateRows(){const rows=filteredCases();$('#case-rows').innerHTML=renderRows(rows);$('#case-count').textContent=rows.length+' 个 Case';persistList();}
function closeMenu(){const menu=$('#row-menu');if(menu)menu.hidden=true;$$('[data-action="row-menu"]').forEach(b=>b.setAttribute('aria-expanded','false'));menuId=null;}
function openRowMenu(button,c){if(menuId===c.id){closeMenu();return;}closeMenu();menuId=c.id;button.setAttribute('aria-expanded','true');const menu=$('#row-menu');menu.innerHTML=`<button role="menuitem" data-action="edit" data-id="${c.id}" ${!editable(c)?'disabled':''}>${icon('edit')}编辑</button><button role="menuitem" data-action="move" data-id="${c.id}" ${!editable(c)?'disabled':''}>${icon('folder')}移动到模块</button>${c.control&&c.owner==='我'?`<button role="menuitem" data-action="take-control" data-id="${c.id}">${icon('device')}接管编辑</button>`:''}<div class="menu-rule"></div><button role="menuitem" data-action="${c.archived?'restore':'archive'}" data-id="${c.id}" ${!editable(c)||A.active(c.id)||c.pending?'disabled':''}>${icon(c.archived?'refresh':'archive')}${c.archived?'恢复到常用列表':'归档'}</button>`;menu.setAttribute('role','menu');menu.hidden=false;const rect=button.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(rect.right-192,innerWidth-200))+'px';menu.style.top=Math.min(rect.bottom+8,innerHeight-menu.offsetHeight-8)+'px';menu.querySelector('button:not(:disabled)')?.focus();}
function renderWorkspace(){const r=currentRun(),s=viewState();$('#app').innerHTML=`<div class="case-workspace"><header class="case-header" id="case-header"></header><div id="definition-strip"></div><main class="workspace-grid" id="workspace-grid"><section class="conversation" aria-label="交互与执行过程"><header class="conversation-title"><div class="od-row"><span class="agent-symbol">A</span><h2>Artemis</h2><span class="small muted">${r?esc(r.config.tool||'HappyCoding'):'HappyCoding'}</span></div><span class="small muted" id="agent-status"></span></header><div class="message-scroll" id="message-scroll"><div class="message-list" id="message-list"></div></div><div class="new-events-bar" id="new-events-bar" hidden></div><footer class="composer" id="composer"></footer></section><div class="split-handle" id="split-handle" role="separator" tabindex="0" aria-label="调整消息流和设备区域比例，按左右方向键" aria-orientation="vertical" aria-valuemin="35" aria-valuemax="65" aria-valuenow="50"></div><section class="device-panel" aria-label="设备与计划"><header class="device-tabs"><nav class="tabs" aria-label="设备区域视图"><button class="tab ${s.rightTab==='live'?'active':''}" data-action="right-tab" data-value="live">${icon('live')}直播</button><button class="tab ${s.rightTab==='plan'?'active':''}" data-action="right-tab" data-value="plan">${icon('file')}TaskPlan<span class="activity-dot" ${r&&ongoing(r)?'':'hidden'}></span></button><button class="tab ${s.rightTab==='replay'?'active':''}" data-action="right-tab" data-value="replay">${icon('play')}回放</button></nav>${ibtn('file','pin-plan',s.pinned?'收起并排计划':'与直播同时查看计划',`aria-pressed="${s.pinned}"`)}</header><div id="device-content" class="device-content"></div></section></main></div>`;renderHeader();renderDefinition();renderMessages();renderComposer();renderRight();bindWorkspace();const scroll=$('#message-scroll');requestAnimationFrame(()=>{scroll.scrollTop=s.scroll??(r?scroll.scrollHeight:0);s.following=scroll.scrollHeight-scroll.clientHeight-scroll.scrollTop<72;});}
function renderHeader(){const c=getCase(),r=currentRun(),runs=c?A.runsFor(c.id):[];$('#case-header').innerHTML=`<div class="header-main"><a class="back-link" href="#/cases">${icon('back')}<span>Cases</span></a><span class="header-divider"></span><div class="case-heading od-fill"><div class="od-row"><h1>${esc(c?.name||newCase.name||'新建 Case')}</h1>${c?.archived?tag('已归档'):''}${r?badge(r.status):c?.pending?'<span class="badge amber">待选设备</span>':''}</div><p class="small muted">${c?`<span class="mono">${c.id}</span> · ${r?`${dateTime(r.started)} · ${r.id}`:'尚未执行'}${r&&runs[0]?.id!==r.id?' · 历史运行':''}`:'描述这次想测试什么，即可开始'}</p></div><div class="header-actions">${c&&runs.length?`<label class="run-picker"><span class="sr-only">切换运行记录</span><select id="run-picker">${c.pending?`<option value="pending" ${!r?'selected':''}>新任务 · 待选设备</option>`:''}${runs.map((x,i)=>`<option value="${x.id}" ${r?.id===x.id?'selected':''}>${i===0?'最近 · ':''}${x.id} · ${dateTime(x.started)} · ${runStates[x.status][0]}</option>`).join('')}</select></label>`:''}${btn('编辑','edit','quiet','edit',`data-id="${c?.id||''}" ${c&&!editable(c)?'disabled':''}`)}${r&&ongoing(r)?`${r.status==='waiting'&&!r.custom?btn(r.resumeRequired?'继续执行':'继续','resume','primary','play'):''}${btn('停止','stop','quiet','stop')}`:r&&c&&!c.archived&&editable(c)?btn('再次运行','rerun','quiet','refresh'):''}${ibtn('help','help','原型说明')}</div></div>`;$('#agent-status').textContent=c?.pending&&!r?'等待选择设备':r?ongoing(r)?r.status==='running'?'正在执行':'等待操作':'执行已结束':'准备就绪';}
function renderDefinition(){const c=getCase(),r=currentRun(),s=viewState(),d=r?.snapshot||c||newCase;$('#definition-strip').innerHTML=`<div class="definition-strip"><div class="definition-summary"><button class="definition-toggle" data-action="toggle-definition" aria-expanded="${s.descriptionOpen}">${icon('down')}<span>测试目标</span></button><p>${esc((r?.intent?.text||d.objective)||'还没有提交目标')}</p>${r?`<span class="definition-version">本次定义 v${r.snapshot.revision}</span>`:''}${btn('查看计划','show-plan','text')}</div>${s.descriptionOpen?`<div class="definition-expanded"><p>${esc(r?.intent?.text||d.objective||'在下方输入这次想测试什么。')}</p>${d.description?`<p class="muted">${esc(d.description)}</p>`:''}<div class="od-cluster small muted"><span>${esc(d.module||'未分类')}</span>${(d.tags||[]).map(tag).join('')}${r?'<span>启动时定义快照 · 编辑只影响后续运行</span>':''}</div></div>`:''}${c&&(c.archived||!editable(c))?`<div class="workspace-notice">${icon(c.archived?'archive':'lock')}<span>${c.archived?'已从常用列表收起，历史仍保留。':c.control?'由'+esc(c.control)+'控制，当前可查看历史。':'由'+esc(c.owner)+'创建，当前为只读。'}</span>${c.control&&c.owner==='我'?btn('接管编辑','take-control','text','',`data-id="${c.id}"`):''}</div>`:''}</div>`;}
function allEvents(r){return r.steps.flatMap((step,index)=>step.events.map(e=>({...e,step:e.step??index}))).sort((a,b)=>a.at-b.at);}
function actualFrames(r){return allEvents(r).filter(e=>e.frame&&['validation','observation'].includes(e.type));}
function frameLabel(kind){return kind==='home'?'首页':kind?.startsWith('password')?'密码页':'邮箱页';}
function latestFrame(r){return actualFrames(r).at(-1)||null;}
function imageButton(r,kind,at,label,eventId,role='result',large=false){if(!kind)return '';return `<button class="evidence-image ${large?'large':''}" data-action="open-image" data-kind="${esc(kind)}" data-at="${at}" data-id="${esc(eventId||'')}" data-role="${role}" aria-label="打开${label}">${phoneSVG(kind,r.config.account,false,false,at)}<span class="image-caption"><strong>${label}</strong><span>${clock(at)} · ${frameLabel(kind)}</span></span>${icon('expand')}</button>`;}
function readableText(text){if(text.length<320)return `<p class="message-text">${esc(text)}</p>`;return `<details class="long-output"><summary><span>${esc(text.slice(0,260))}…</span><span class="text-link">展开全文</span></summary><p class="message-text">${esc(text)}</p></details>`;}
function rawRecord(e){return `<details class="raw-record" data-preserve="raw-${esc(e.id)}"><summary>${icon('code')}工具参数与原始记录</summary><pre>${esc(typeof e.tool==='string'?e.tool:JSON.stringify(e.tool||{},null,2))}</pre><dl><dt>事件</dt><dd>${esc(e.id)}</dd>${e.actionId?`<dt>关联动作</dt><dd>${esc(e.actionId)}</dd>`:''}${e.callId?`<dt>调用</dt><dd>${esc(e.callId)}</dd>`:''}</dl></details>`;}
function messageShell(id,role,title,at,body,extra=''){return `<article class="message ${role} ${extra}" id="msg-${esc(id)}" data-message-id="${esc(id)}"><div class="message-avatar">${role==='user'?'我':role==='result'?icon('check'):'A'}</div><div class="message-body"><div class="message-byline"><strong>${title}</strong><time>${clock(at)}</time></div>${body}</div></article>`;}
function messagesForRun(r){const s=viewState(),events=allEvents(r),last=events.at(-1),intent=r.intent||{id:r.id+'-goal',at:r.started,text:r.snapshot.objective};let html=messageShell(intent.id,'user','我',intent.at,readableText(intent.text));html+=`<div class="device-used">${icon('device')}<span>已使用 <strong>${esc(r.config.device)}</strong></span><time>${clock(r.started)}</time></div>`;
 const instructions=r.instructions.map(i=>({id:i.id+'-user',at:i.at,type:'user-instruction',instruction:i})),adjustments=(r.adjustments||[]).map((a,i)=>({id:r.id+'-plan-'+i,at:a.at,type:'plan-update',text:a.text,step:a.step}));
 const combined=[...events.filter(e=>e.type!=='model'),...instructions,...adjustments].sort((a,b)=>a.at-b.at);
 for(const e of combined){const selected=s.selected===e.id,current=e.id===last?.id,step=r.steps[e.step];
  if(e.type==='user-instruction'){html+=messageShell(e.id,'user','我 · 补充指令',e.at,readableText(e.instruction.text)+`<span class="instruction-state">${e.instruction.state==='pending'?(ongoing(r)?'待记录':'运行结束，采纳未确认'):'已记录 · 采纳未确认'}</span>`);continue;}
  if(e.type==='plan-update'){html+=`<div class="stream-event" id="msg-${e.id}">${icon('file')}<div><strong>计划调整</strong><p>${esc(e.text)}</p><button class="text-link" data-action="show-plan">查看计划更新</button></div><time>${clock(e.at)}</time></div>`;continue;}
  if(e.type==='output'||e.type==='model-output'){html+=messageShell(e.id,'agent',e.source==='legacy-example'?'原项目示例输出':'模型输出',e.at,readableText(e.text)+`<div class="decision-context"><span class="evidence-label">决策截图 · 本次调用实际输入</span>${e.decisionFrame?imageButton(r,e.decisionFrame,e.at,'决策截图',e.id,'decision',selected||current):'<span class="missing-evidence">未记录输入截图，无法确认本次模型实际看到了哪一帧。</span>'}</div>`+rawRecord(e),selected?'selected':'');continue;}
  if(['action','retry'].includes(e.type)){const verification=events.find(v=>v.actionId===e.id);html+=messageShell(e.id,'agent','Artemis',e.at,`<div class="action-card ${selected?'selected':''}"><button class="action-card-head" data-action="select-message" data-id="${e.id}"><span class="od-field"><span class="action-type">${e.type==='retry'?'ACTION · RETRY':'ACTION'}</span><strong>${esc(e.type==='retry'?'重试点击下一步':step?.name||'执行动作')}</strong></span>${badge('sent','step')}</button><p class="action-copy">${esc(e.text)}</p><div class="action-id mono">${e.id}</div>${rawRecord(e)}${verification?`<div class="action-result">${badge(verification.status||'insufficient','step')}<span>${esc(verification.text)}</span></div>`:'<div class="action-result muted">尚无与本动作明确关联的校验结果。</div>'}</div>`);continue;}
  if(e.type==='validation'||e.type==='observation'){const issue=['failed','insufficient'].includes(e.status),full=selected||current||issue;html+=messageShell(e.id,'agent',e.status==='recovered'?'恢复校验':'结果校验',e.at,`<div class="validation ${issue?'issue':''}"><div class="od-row">${badge(e.status||'insufficient','step')}<button class="text-link" data-action="select-message" data-id="${e.id}">${selected?'当前记录':'查看此记录'}</button></div>${readableText(e.text)}${e.status==='failed'?`<div class="expectation"><span>预期</span><p>${esc(step.expected)}</p></div>`:''}${e.frame?`<div class="evidence-label">动作结果截图 <span class="mono">${e.actionId?esc(e.actionId):'原记录未提供 actionId'}</span></div>${imageButton(r,e.frame,e.at,'动作结果',e.id,'result',full)}`:'<div class="missing-evidence">未记录动作结果截图，不以其他帧替代。</div>'}${rawRecord(e)}</div>`,selected?'selected':'');continue;}
  html+=`<div class="stream-event" id="msg-${e.id}">${icon(e.type==='control'?'stop':'info')}<div><strong>${e.type==='instruction'?'指令状态':e.type==='control'?'运行控制':'执行事件'}</strong><p>${esc(e.text)}</p>${e.tool?rawRecord(e):''}</div><time>${clock(e.at)}</time></div>`;
 }
 if(!combined.some(e=>e.type==='output'||e.type==='model-output'))html+=`<div class="source-note">${icon('info')}<span>这份记录未保存原始模型输出与输入截图，当前只显示已有动作和校验事件。</span></div>`;
 if(r.custom&&ongoing(r))html+=`<div class="stream-event">${icon('clock')}<div><strong>等待执行接入</strong><p>目标与设备已记录；当前没有该场景的真实执行输出。</p></div></div>`;
 if(!ongoing(r))html+=resultMessage(r);return html;
}
function resultMessage(r){const passed=r.status==='passed',incomplete=r.steps.filter(x=>!['verified','recovered'].includes(x.status));return messageShell(r.id+'-result','result','执行结论',r.ended||r.started,`<div class="result-message"><div class="od-row">${badge(r.status)}<h3>${passed?'测试目标已完成':r.status==='stopped'?'本次执行已停止':'测试目标未完成'}</h3></div><p>${passed?'登录与首页均已验证。首次点击下一步的异常已在重试后恢复。':incomplete.length?'尚未完成：'+incomplete.map(x=>x.name).join('、')+'。':'已有验证结果已保留。'}</p>${r.steps.some(x=>x.recovery)?'<p class="muted">首次失败和恢复证据均保留；恢复不等同于整次运行通过。</p>':''}<div class="od-cluster">${btn('回放本次执行','open-replay','small','play')}${r.steps.some(x=>x.issue)?btn('查看异常证据','result-evidence','text','file'):''}<button class="btn text" data-action="run-facts">本次运行信息</button></div></div>`);}
function emptyMessages(c){return `<div class="workspace-welcome"><span class="welcome-symbol">${logo()}</span><div class="eyebrow">ARTEMIS WORKSPACE</div><h2>${c?.objective?'准备好验证这个目标了吗？':'这次想测试什么？'}</h2><p>${c?esc(c.objective||'输入测试目标，提交后选择执行设备。'):'描述要完成的操作、预期结果，或需要重点观察的问题。'}</p>${c&&c.objective?btn('提交这个目标','submit-existing','','send',c.archived||!editable(c)?'disabled':''):`<button class="example-prompt" data-action="example-goal"><span>验证邮箱登录流程，确认密码页与首页</span>${icon('arrow')}</button>`}<span class="welcome-footnote">提交目标后，在这里选择执行设备</span></div>`;}
function deviceCard(c){const p=c.pending,available=A.deviceCatalog.filter(d=>d.state==='ready'&&!offline);return `<article class="message agent"><div class="message-avatar">A</div><div class="message-body"><div class="message-byline"><strong>Artemis</strong><time>${clock(p.at)}</time></div><p class="message-text">已收到测试目标，选择设备后开始执行。</p><section class="device-choice"><header><div><h3>选择执行设备</h3><p>任务已提交，现在只差一台设备</p></div><button class="icon-btn" data-action="refresh-devices" aria-label="刷新设备" ${deviceRefreshing?'disabled':''}>${icon('refresh')}</button></header>${deviceRefreshing?'<div class="progress-line" role="status">正在刷新设备状态…</div>':''}<div class="device-options">${A.deviceCatalog.map(d=>`<label class="device-option ${p.deviceId===d.id?'selected':''} ${d.state!=='ready'||offline?'unavailable':''}"><input type="radio" name="execution-device" value="${d.id}" ${p.deviceId===d.id?'checked':''} ${d.state!=='ready'||offline?'disabled':''}><span class="device-glyph">${icon('device')}</span><span class="od-field od-fill"><strong>${d.name}</strong><small>${d.detail}</small></span><span class="device-status ${d.state==='ready'&&!offline?'available':''}">${offline?'未连接':{ready:'已连接 · 可用',busy:'已连接 · 占用中',offline:'未连接'}[d.state]}</span></label>`).join('')}</div>${!available.length?`<div class="device-empty"><strong>暂无可用设备</strong><p>连接设备并授权调试后，刷新列表重试。</p><button class="text-link" data-action="device-guide">连接指引 ${icon('right')}</button></div>`:''}<footer><span class="small muted">设备状态为本地演示</span>${btn('选择并开始','start-device','primary','play',!available.some(d=>d.id===p.deviceId)||deviceRefreshing?'disabled':'')}</footer></section></div></article>`;}
function renderMessages(){const c=getCase(),r=currentRun(),s=viewState(),scroll=$('#message-scroll'),existing=scroll?.scrollTop||0,root=$('#message-list');if(!root)return;const expanded=[...root.querySelectorAll('details[open][data-preserve]')].map(el=>el.dataset.preserve);root.innerHTML=r?messagesForRun(r):c?.pending?messageShell(c.pending.id,'user','我',c.pending.at,readableText(c.pending.text))+deviceCard(c):emptyMessages(c);expanded.forEach(id=>root.querySelector(`[data-preserve="${CSS.escape(id)}"]`)?.setAttribute('open',''));if(scroll)scroll.scrollTop=existing;updateNewEvents();}
function renderComposer(){const c=getCase(),r=currentRun(),s=viewState(),pending=c?.pending&&!r,readOnly=c&&(!editable(c)||c.archived),otherActive=c&&A.active(c.id)&&r?.id!==A.active(c.id).id;const placeholder=ongoing(r)?'补充指令，例如：先确认密码页，不要连续重复点击':r?'输入下一次测试目标，开始新的运行…':'这次想测试什么？';$('#composer').innerHTML=`<form id="composer-form"><label class="composer-label" for="composer-input">${ongoing(r)?'补充指令':r?'下一次测试':'测试意图'}</label><textarea id="composer-input" maxlength="4000" rows="2" placeholder="${placeholder}" ${pending||readOnly||otherActive?'disabled':''}>${esc(s.input)}</textarea><p class="field-error" id="composer-error" hidden></p><div class="composer-footer"><span>${readOnly?'当前只读':pending?'目标已提交，请先选择设备':otherActive?'另一次运行正在执行':ongoing(r)?'指令归属本次运行':'HappyCoding · 提交后选择设备'}</span><div class="od-row">${!c?'<button type="button" class="btn text small" data-action="edit">补充信息</button>':''}<button class="send-button" type="submit" aria-label="${ongoing(r)?'提交补充指令':'提交测试目标'}" ${pending||readOnly||otherActive?'disabled':''}>${icon('send')}</button></div></div></form>`;}
function updateNewEvents(){const s=viewState(),bar=$('#new-events-bar');if(!bar)return;bar.hidden=!s.unread;bar.innerHTML=`<button data-action="follow-messages">${s.unread} 条新消息 · 回到最新 ${icon('down')}</button>`;}

function renderRight(){const s=viewState(),root=$('#device-content');if(!root)return;const expanded=[...root.querySelectorAll('details[open][data-plan-key]')].map(x=>x.dataset.planKey);const scroll=$('.plan-scroll',root)?.scrollTop||0;$$('[data-action="right-tab"]').forEach(b=>{b.classList.toggle('active',b.dataset.value===s.rightTab);b.setAttribute('aria-selected',b.dataset.value===s.rightTab);});$('[data-action="pin-plan"]')?.setAttribute('aria-pressed',s.pinned);root.classList.toggle('plan-pinned',s.pinned&&s.rightTab==='live');root.innerHTML=s.rightTab==='plan'?renderPlan():s.rightTab==='replay'?renderReplay():renderLive()+(s.pinned?`<aside class="pinned-plan">${renderPlan(true)}</aside>`:'');expanded.forEach(key=>root.querySelector(`[data-plan-key="${CSS.escape(key)}"]`)?.setAttribute('open',''));const plan=$('.plan-scroll',root);if(plan)plan.scrollTop=scroll;}
function renderLive(){const c=getCase(),r=currentRun(),s=viewState();if(!r)return `<div class="live-view"><div class="viewer-meta"><span class="od-row">${icon('device')}等待连接设备</span><span class="connection-badge">未连接</span></div><div class="device-waiting"><div class="device-outline">${icon('device')}</div><h2>${c?.pending?'选择设备后开始':'设备画面将在这里显示'}</h2><p>${c?.pending?'左侧目标已提交，等待选择执行设备。':'提交测试目标，然后在消息中选择设备。'}</p></div><div class="viewer-footer"><span>直播连接与任务状态分别记录</span></div></div>`;
 const last=latestFrame(r),frame=!s.connected&&ongoing(r)?s.lastFrame:last?.frame,at=!s.connected&&ongoing(r)?s.lastAt:last?.at;
 return `<div class="live-view"><div class="viewer-meta"><span class="od-row">${icon('device')}${esc(r.config.device)}</span><span class="connection-badge ${ongoing(r)?s.connected?'green':'amber':''}">${!ongoing(r)?'执行已结束':s.connected?'直播已连接 · 模拟':'直播连接中断'}</span></div>${!ongoing(r)?`<div class="live-state ended"><div><strong>本次执行已结束</strong><span>${dateTime(r.ended)} · 保留最后可用画面</span></div>${btn('查看回放','open-replay','small','play')}</div>`:!s.connected?`<div class="live-state disconnected"><div><strong>直播连接中断</strong><span>最后画面 ${at?clock(at):'尚未收到'} · 任务${r.status==='running'?'仍在执行':'等待操作'}</span></div>${btn('重新连接','reconnect','small','refresh',offline?'disabled':'')}</div>`:''}<div class="live-canvas">${frame?`<button class="live-shot" data-action="open-image" data-kind="${frame}" data-at="${at}" data-id="${last?.id||''}" data-role="result" aria-label="放大当前设备画面">${phoneSVG(frame,r.config.account,false,false,at)}</button>`:`<div class="device-waiting"><div class="device-outline">${icon('device')}</div><h2>等待首帧画面</h2><p>${r.custom?'尚未接入该场景的设备执行。':'已创建运行，等待页面观察结果。'}</p></div>`}</div><div class="viewer-footer"><span>${at?'最后画面 '+clock(at):'尚无画面'} · 示例重建</span><span class="od-row">任务 ${badge(r.status)}</span></div></div>`;
}
function planData(r){if(!r)return null;const versions=r.planVersions||[];const selected=viewState().selectedVersion;const version=selected==='latest'?versions.at(-1):versions.find((v,i)=>String(v.id??i)===selected);if(version)return version.content??version.plan??version.raw??version;return r.taskPlan??r.task_plan??r.rawTaskPlan??null;}
function planValue(value,key='root',depth=0){if(value===null)return '<span class="muted">null</span>';if(typeof value!=='object')return `<div class="plan-text">${esc(String(value))}</div>`;if(Array.isArray(value))return `<div class="plan-children">${value.map((v,i)=>planValue(v,key+'-'+i,depth+1)).join('')}</div>`;const title=value.title??value.name??value.label??value.id??'任务内容',status=value.status;const kind=value.type??value.kind;const fields=Object.entries(value).filter(([k])=>!['title','name','label'].includes(k)||k!==(value.title!==undefined?'title':value.name!==undefined?'name':'label'));return `<details class="plan-node" data-plan-key="${esc(key)}" ${depth<3?'open':''}><summary><span class="od-field"><strong>${esc(String(title))}</strong>${kind?`<small>${esc(String(kind))}</small>`:''}</span>${status?`<span class="badge ${['completed','done','passed','verified'].includes(status)?'green':['running','active','in_progress'].includes(status)?'blue':''}">${esc(String(status))}</span>`:''}</summary><div class="plan-node-content">${fields.map(([k,v])=>`<div class="plan-property"><span class="plan-key">${esc(k)}</span>${planValue(v,key+'-'+k,depth+1)}</div>`).join('')}</div></details>`;}
function renderPlan(pinned=false){const r=currentRun(),raw=planData(r),versions=r?.planVersions||[];return `<div class="plan-panel"><header class="plan-panel-head"><div><h2>TaskPlan</h2><p>计划目标、组织方式与检查条件</p></div>${pinned?ibtn('close','pin-plan','收起并排计划'):''}</header>${versions.length?`<label class="plan-version-label">计划版本<select id="plan-version"><option value="latest">最新版本</option>${versions.map((v,i)=>`<option value="${esc(v.id??i)}" ${viewState().selectedVersion===String(v.id??i)?'selected':''}>${esc(v.title||'版本 '+(i+1))}${v.at?' · '+clock(v.at):''}</option>`).join('')}</select></label>`:''}<div class="plan-scroll">${!r?'<div class="plan-empty"><h3>尚未收到执行计划</h3><p>选择设备并开始后，计划会在这里显示。</p></div>':raw?`<div class="plan-source">按记录中的原始字段与层级展示</div>${planValue(raw)}<details class="raw-record"><summary>查看完整原文</summary><pre>${esc(typeof raw==='string'?raw:JSON.stringify(raw,null,2))}</pre></details>`:`<div class="plan-source missing"><strong>仅有阶段摘要</strong><p>此运行未保存完整原始 TaskPlan。以下保留已有目标与状态，不补写层级、循环或断言结构。</p></div><div class="legacy-plan">${r.steps.map((step,i)=>`<div class="legacy-task"><div class="od-row"><span class="task-index">${i+1}</span><strong>${step.name}</strong>${badge(step.status,'step')}</div><p><span>已有预期：</span>${esc(step.expected)}</p></div>`).join('')}</div>`}${r&&(r.adjustments||[]).length?`<section class="plan-updates"><h3>已记录的计划调整</h3>${r.adjustments.map(a=>`<div class="plan-update"><time>${clock(a.at)}</time><p>${esc(a.text)}</p></div>`).join('')}</section>`:''}<p class="plan-footnote">计划状态不等于测试通过率；测试结论见消息流末尾。</p></div></div>`;}
function renderReplay(){const r=currentRun(),s=viewState();if(!r)return '<div class="device-waiting"><h2>还没有可回放记录</h2><p>执行产生画面后，可在这里按事件回看。</p></div>';const frames=actualFrames(r);s.replay=Math.max(0,Math.min(s.replay,frames.length-1));const e=frames[s.replay];return `<div class="replay-view"><div class="viewer-meta"><span class="od-row">${icon('play')}${r.id} · 事件回放</span><span>${e?clock(e.at):'暂无画面'}</span></div><div class="replay-event">${e?`<span class="mono">${e.id}</span><p>${esc(e.text)}</p><span class="badge">动作结果截图</span>`:'尚未收到可用截图'}</div><div class="live-canvas">${e?`<button class="live-shot" data-action="open-image" data-kind="${e.frame}" data-at="${e.at}" data-id="${e.id}" data-role="result" aria-label="打开回放画面">${phoneSVG(e.frame,r.config.account,false,false,e.at)}</button>`:`<div class="device-waiting">${icon('file')}<p>没有关联画面，无法回放。</p></div>`}</div><div class="replay-controls">${ibtn(s.playing?'pause':'play','play-replay',s.playing?'暂停回放':'播放事件回放',!frames.length?'disabled':'')}<div class="od-field od-fill"><label class="sr-only" for="replay-position">回放位置</label><input id="replay-position" type="range" min="0" max="${Math.max(0,frames.length-1)}" value="${s.replay}" ${!frames.length?'disabled':''}><div class="replay-labels"><span>${e?duration((e.at-r.started)/1000):'00:00'}</span><span>${frames.length?duration((frames.at(-1).at-r.started)/1000):'00:00'}</span></div></div>${e?ibtn('arrow','replay-message','定位关联消息',`data-id="${e.id}"`):''}</div><div class="viewer-footer"><span>按记录切换画面 · 非真实录屏</span>${btn(ongoing(r)?'回到实时':'返回直播位置','back-live','text')}</div></div>`;}
function stopReplay(){clearInterval(playTimer);playTimer=null;for(const v of workspaceStates.values())v.playing=false;}
function toggleReplay(){const r=currentRun(),s=viewState();if(!r)return;if(s.playing){stopReplay();renderRight();return;}const frames=actualFrames(r);if(!frames.length)return;if(s.replay>=frames.length-1)s.replay=0;s.playing=true;renderRight();playTimer=setInterval(()=>{if(currentRun()?.id!==r.id){stopReplay();return;}if(s.replay>=actualFrames(r).length-1){stopReplay();renderRight();return;}s.replay++;renderRight();},1500);}
function bindWorkspace(){const scroll=$('#message-scroll');scroll.addEventListener('scroll',()=>{const s=viewState();s.scroll=scroll.scrollTop;s.following=scroll.scrollHeight-scroll.clientHeight-scroll.scrollTop<72;},{passive:true});const handle=$('#split-handle'),grid=$('#workspace-grid');function setRatio(percent){const value=Math.max(35,Math.min(65,percent));grid.style.setProperty('--left-share',value+'%');handle.setAttribute('aria-valuenow',String(Math.round(value)));try{sessionStorage.setItem('artemis-split',String(value));}catch{}}try{const value=sessionStorage.getItem('artemis-split');if(value)setRatio(Number(value));}catch{}handle.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();setRatio(Number(handle.getAttribute('aria-valuenow'))+(e.key==='ArrowRight'?2:-2));});handle.addEventListener('pointerdown',e=>{handle.setPointerCapture(e.pointerId);const box=grid.getBoundingClientRect();const move=ev=>setRatio((ev.clientX-box.left)/box.width*100);const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);});}
function refreshRun(r){if(screen.kind==='list'){updateRows();return;}if(currentRun()?.id!==r.id)return;const s=viewState(),scroll=$('#message-scroll');renderHeader();if(s.following){renderMessages();scroll.scrollTop=scroll.scrollHeight;s.scroll=scroll.scrollTop;}else{s.unread++;updateNewEvents();}if(s.rightTab==='live'||s.rightTab==='plan')renderRight();if(!ongoing(r))renderComposer();}
function followMessages(){const s=viewState();s.following=true;s.unread=0;renderMessages();const scroll=$('#message-scroll');scroll.scrollTop=scroll.scrollHeight;s.scroll=scroll.scrollTop;}
function locateMessage(id){const s=viewState();s.selected=id;s.following=false;renderMessages();const el=document.getElementById('msg-'+id);if(el){const scroll=$('#message-scroll');scroll.scrollTop+=el.getBoundingClientRect().top-scroll.getBoundingClientRect().top-20;s.scroll=scroll.scrollTop;el.classList.add('selected');}}

function dialog(title,body,actions='',subtitle='',cls=''){const el=$('#modal');if(!el.open)dialogReturn=document.activeElement;el.className=cls;el.innerHTML=`<header class="dialog-head"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${ibtn('close','close-dialog','关闭')}</header><div class="dialog-body">${body}</div><footer class="dialog-actions">${actions||btn('关闭','close-dialog')}</footer>`;if(!el.open)el.showModal();}
function closeDialog(){const el=$('#modal');if(el?.open)el.close();unsavedEdit=false;modalKind='';modalContext={};if(dialogReturn?.isConnected)dialogReturn.focus();}
function confirmDialog(title,text,label,callback){modalKind='confirm';modalContext={callback};dialog(title,`<p>${esc(text)}</p>`,btn('取消','close-dialog')+btn(label,'confirm','primary'));}
function field(id,label,control,hint=''){return `<div class="field"><label for="${id}">${label}</label>${control}${hint?`<p class="hint">${hint}</p>`:''}<p class="field-error" id="${id}-error" hidden></p></div>`;}
function editCase(c){if(c&&!editable(c))return;const d=c||newCase;modalKind='edit';modalContext={caseId:c?.id};dialog(c?'编辑 Case':'新建 Case',`<form id="edit-form" novalidate><div class="form-section">${field('edit-name','Case 名称（必填）',`<input id="edit-name" name="name" maxlength="100" required aria-describedby="edit-name-error" value="${esc(d.name)}" placeholder="例如：邮箱登录测试">`)}${c?.objective?field('edit-objective','测试目标',`<textarea id="edit-objective" name="objective" rows="4" maxlength="4000" required aria-describedby="edit-objective-error">${esc(d.objective)}</textarea>`):''}<details class="optional-info" ${d.description||d.tags?.length?'open':''}><summary>分类、标签与补充说明（选填）</summary><div class="form-section">${field('edit-module','分类',`<select id="edit-module" name="module">${options(A.modules,d.module)}</select>`)}${field('edit-tags','标签',`<input id="edit-tags" name="tags" value="${esc((d.tags||[]).join('，'))}" maxlength="120" placeholder="例如：冒烟，核心路径">`,'使用逗号分隔，最多 6 个标签。')}${field('edit-description','补充说明',`<textarea id="edit-description" name="description" rows="3" maxlength="4000">${esc(d.description)}</textarea>`)}</div></details></div></form>`,btn('取消','close-dialog')+`<button type="submit" form="edit-form" class="btn primary">${c?'保存':'创建并进入工作区'}</button>`,c?'更新 Case 信息，不改写历史运行':'填写 Case 基本信息，测试目标进入工作区后再输入');}
function inferName(text){const first=text.split(/[。！？\n]/)[0].trim();return first.length>28?first.slice(0,28):first||'未命名 Case';}
function submitGoal(text){let c=getCase();if(!text.trim())return;if(c&&(!editable(c)||c.archived))return;if(c&&A.active(c.id)){toast('这个 Case 已有进行中的运行，请在当前运行中补充指令。');return;}if(!c){c=A.saveCase({name:newCase.name.trim()||inferName(text),objective:text,description:newCase.description,module:newCase.module,tags:newCase.tags,config:A.clone(A.defaults)});newCase={name:'',objective:'',description:'',module:'账号与登录',tags:[]};try{sessionStorage.removeItem('artemis-new-draft');}catch{}}A.submitIntent(c,text);viewState().input='';if($('#composer-input'))$('#composer-input').value='';const stateKey=c.id+':pending';workspaceStates.delete(stateKey);go('case/'+c.id+'/pending');}
function showRunFacts(r){modalKind='facts';dialog('本次运行信息',`<dl class="facts"><dt>Case</dt><dd>${esc(r.snapshot.name)} · ${r.caseId}</dd><dt>运行</dt><dd>${r.id} · ${runStates[r.status][0]}</dd><dt>开始</dt><dd>${dateTime(r.started)}</dd><dt>结束</dt><dd>${r.ended?dateTime(r.ended):'尚未结束'}</dd><dt>定义版本</dt><dd>v${r.snapshot.revision}</dd><dt>设备</dt><dd>${esc(r.config.device)}</dd><dt>执行工具</dt><dd>${esc(r.config.tool)}</dd></dl><p class="small muted" style="margin-top:16px">这是本次启动时的记录；编辑 Case 不会改变历史快照。</p>`);}
function showHelp(){dialog('Artemis 工作区',`<p>提交目标，在消息中选择设备，然后查看执行过程。历史运行在标题附近切换，结束结论保留在消息末尾。</p><p>当前是本地交互原型：HappyCoding、设备连接和执行均未接入真实服务，设备画面为示例重建。新任务默认保留证据，不显示账号、模型或构建配置。</p><p>完整演示场景为邮箱登录。原项目没有提供完整 TaskPlan 和真实模型调用输入截图，缺失内容会明确标注；不会把旧版阶段摘要包装为原始模型决策。</p><p>离开工作区不停止当前运行；关闭整个页面后，模拟执行会等待下次继续。</p>`);}
function showImage(kind,at,id,role){const r=currentRun();if(!r)return;modalKind='image';modalContext={kind,at,id,role,zoom:1};renderImageDialog();}
function renderImageDialog(){const r=currentRun(),d=modalContext;dialog(d.role==='decision'?'决策截图':'动作结果截图',`<div class="image-dialog-frame">${phoneSVG(d.kind,r.config.account,false,false,d.at)}</div><p class="small muted">${esc(d.id)} · ${clock(d.at)} · 示例重建</p>`,`<span class="small muted" style="margin-right:auto">${Math.round(d.zoom*100)}%</span>${ibtn('back','zoom-out','缩小')}${ibtn('plus','zoom-in','放大')}${btn('关闭','close-dialog')}`,'仅查看所选图片，右侧直播保持原状态','image-dialog');$('.image-dialog-frame svg').style.width=(300*d.zoom)+'px';}

document.addEventListener('click',e=>{
 const control=e.target.closest('[data-action]');
 if(!control){const link=e.target.closest('a[href^="#/"]');if(link){e.preventDefault();go(link.getAttribute('href').slice(2));return;}const row=e.target.closest('[data-open-case]');if(row&&!e.target.closest('button,input,select,a')){go('case/'+row.dataset.openCase);return;}if(!e.target.closest('#row-menu'))closeMenu();return;}
 if(control.disabled)return;const action=control.dataset.action,id=control.dataset.id,r=currentRun(),c=id?A.getCase(id)||getCase():getCase(),s=['workspace','new'].includes(screen.kind)?viewState():null;
 if(action==='back-list')return go('cases');if(action==='new'){rememberView();return editCase(null);}
 if(action==='settings')return dialog('设置','<dl class="facts"><dt>执行工具</dt><dd>HappyCoding</dd><dt>证据保留</dt><dd>默认保留视频与日志</dd><dt>执行设备</dt><dd>提交目标后，在消息流中选择</dd></dl><p class="small muted" style="margin-top:16px">以上为当前默认设置。服务连接与可配置项尚未接入。</p>');
 if(action==='help')return showHelp();if(action==='close-dialog')return closeDialog();
 if(action==='confirm'){const callback=modalContext.callback;closeDialog();return callback?.();}
 if(action==='module'){list.module=control.dataset.value;list.scroll=0;persistList();return render();}
 if(action==='list-view'){list.view=control.dataset.value;persistList();return render();}
 if(action==='clear-filters'){list={...list,search:'',module:'全部 Case',tag:'',owner:'',archive:'active',controlled:false};persistList();return render();}
 if(action==='row-menu'){e.stopPropagation();return openRowMenu(control,A.getCase(id));}
 if(action==='edit'){closeMenu();return editCase(c);}
 if(action==='list-settings'){dialog('筛选与排序',`<form id="filter-form"><div class="form-section">${field('filter-sort','排序',`<select id="filter-sort" name="sort"><option value="updated" ${list.sort==='updated'?'selected':''}>最近更新</option><option value="name" ${list.sort==='name'?'selected':''}>Case 名称</option></select>`)}<label class="check-row"><input name="controlled" type="checkbox" ${list.controlled?'checked':''}>仅看其他设备控制中的 Case</label></div></form>`,btn('取消','close-dialog')+'<button type="submit" form="filter-form" class="btn primary">应用</button>');return;}
 if(action==='move'){closeMenu();if(!editable(c))return;dialog('移动到模块',`<form id="move-form" data-id="${c.id}">${field('move-module','功能模块',`<select id="move-module" name="module">${options(A.modules,c.module)}</select>`)}</form>`,btn('取消','close-dialog')+'<button type="submit" form="move-form" class="btn primary">移动</button>');return;}
 if(action==='archive'){closeMenu();if(!editable(c)||A.active(c.id)||c.pending)return;return confirmDialog('归档这个 Case？','将从常用列表收起，测试定义和历史运行仍保留。以后可通过“已归档”筛选找到并恢复。','归档',()=>{c.archived=true;save();render();toast('已从常用列表收起，历史记录仍保留。');});}
 if(action==='restore'){if(!editable(c))return;c.archived=false;save();closeMenu();render();toast('已恢复到常用列表。');return;}
 if(action==='take-control'){if(c.owner!=='我')return;return confirmDialog('接管编辑？','本地原型将解除其他工作站的控制标记。已有运行继续保留。','接管',()=>{c.control='';save();render();});}
 if(action==='toggle-definition'){s.descriptionOpen=!s.descriptionOpen;return renderDefinition();}
 if(action==='example-goal'){s.input='验证邮箱登录流程：输入邮箱，进入密码页并完成登录，确认首页可见。';$('#composer-input').value=s.input;$('#composer-input').focus();return;}
 if(action==='submit-existing')return submitGoal(c.objective);
 if(action==='rerun'){const activeRun=A.active(c.id);if(activeRun){go(`case/${c.id}/run/${activeRun.id}`);return toast('该 Case 已有进行中的运行。');}return submitGoal(r.intent?.text||r.snapshot.objective);}
 if(action==='start-device'){if(!c?.pending||offline)return;const device=A.deviceCatalog.find(d=>d.id===c.pending.deviceId);if(!device||device.state!=='ready')return toast('请选择可用设备。');control.disabled=true;control.innerHTML='正在连接…';setTimeout(()=>{const run=A.startPending(c,device.id);if(!run)return toast('无法开始，请刷新设备状态后重试。');if(run.status==='running')A.advance(run);go(`case/${c.id}/run/${run.id}`);},400);return;}
 if(action==='refresh-devices'){deviceRefreshing=true;renderMessages();setTimeout(()=>{deviceRefreshing=false;if(getCase()?.id===c.id&&!currentRun())renderMessages();toast(offline?'仍无可用连接，请检查网络和设备。':'设备状态已刷新。');},500);return;}
 if(action==='device-guide')return dialog('连接执行设备','<p>连接目标设备，完成调试授权，并确保设备未被其他任务占用；然后在设备卡片内刷新状态。</p><p class="muted">当前页面仅提供本地示例设备列表，没有真实连接服务。实际连接方式、权限和设备发现机制仍需接入确认。</p>');
 if(action==='stop')return confirmDialog('停止本次执行？','保留已有消息和证据。未完成目标不会标记为通过。','停止执行',()=>{A.stop(r);refreshRun(r);});
 if(action==='resume'){if(!r||r.custom)return;r.config.mode='auto';A.advance(r,true);refreshRun(r);return;}
 if(action==='select-message'){s.selected=id;s.following=false;renderMessages();return;}
 if(action==='follow-messages')return followMessages();
 if(action==='right-tab'){stopReplay();s.rightTab=control.dataset.value;return renderRight();}
 if(action==='show-plan'){stopReplay();s.rightTab='plan';return renderRight();}
 if(action==='pin-plan'){stopReplay();s.pinned=!s.pinned;s.rightTab='live';return renderRight();}
 if(action==='open-replay'){stopReplay();s.rightTab='replay';s.replay=0;return renderRight();}
 if(action==='back-live'){stopReplay();s.rightTab='live';return renderRight();}
 if(action==='play-replay')return toggleReplay();
 if(action==='replay-message')return locateMessage(id);
 if(action==='result-evidence'){const event=allEvents(r).find(x=>x.status==='failed');if(event)locateMessage(event.id);return;}
 if(action==='run-facts')return showRunFacts(r);
 if(action==='open-image')return showImage(control.dataset.kind,Number(control.dataset.at),id,control.dataset.role);
 if(action==='zoom-in'||action==='zoom-out'){modalContext.zoom=Math.max(.75,Math.min(2,modalContext.zoom+(action==='zoom-in'? .25:-.25)));return renderImageDialog();}
 if(action==='reconnect'){if(offline)return;s.connected=true;s.lastAt=null;s.lastFrame=null;r.connectionEvents.push({at:Date.now(),state:'connected'});save();renderRight();toast('本地模拟直播已重新连接。');return;}
});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='case-search'){list.search=el.value;updateRows();}if(el.id==='composer-input'){viewState().input=el.value;if(screen.kind==='new'){newCase.objective=el.value;try{sessionStorage.setItem('artemis-new-draft',JSON.stringify(newCase));}catch{}}}if(el.id==='replay-position'){stopReplay();viewState().replay=Number(el.value);renderRight();}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='tag-filter'){list.tag=el.value==='全部'?'':el.value;updateRows();}if(el.id==='owner-filter'){list.owner=el.value==='全部'?'':el.value;updateRows();}if(el.id==='archive-filter'){list.archive=el.value;rememberView();persistList();render();}if(el.id==='run-picker'){go(el.value==='pending'?`case/${getCase().id}/pending`:`case/${getCase().id}/run/${el.value}`);}if(el.name==='execution-device'){getCase().pending.deviceId=el.value;save();renderMessages();}if(el.id==='plan-version'){viewState().selectedVersion=el.value;renderRight();}});
function validationError(el,text){el.setAttribute('aria-invalid',text?'true':'false');const error=$('#'+el.id+'-error');if(error){error.hidden=!text;error.textContent=text;}}
document.addEventListener('focusout',e=>{if(e.target.id==='edit-objective')validationError(e.target,e.target.value.trim()?'':'请描述测试目标。');if(e.target.id==='edit-name')validationError(e.target,e.target.value.trim()?'':'请填写 Case 名称。');});
document.addEventListener('submit',e=>{
 const form=e.target;if(!form.matches('#composer-form,#edit-form,#filter-form,#move-form'))return;e.preventDefault();
 if(form.id==='composer-form'){const input=$('#composer-input'),text=input.value.trim();if(!text){$('#composer-error').textContent='请先描述测试目标或补充指令。';$('#composer-error').hidden=false;input.focus();return;}const r=currentRun();if(ongoing(r)){if(!editable(getCase()))return;A.addInstruction(r,text);viewState().input='';input.value='';followMessages();toast('补充指令已提交，采纳状态待确认。');}else{input.value='';viewState().input='';submitGoal(text);}return;}
 if(form.id==='edit-form'){const c=A.getCase(modalContext.caseId),fd=new FormData(form),name=String(fd.get('name')||'').trim(),objective=c?(fd.has('objective')?String(fd.get('objective')).trim():c.objective||''):'';if(!name){validationError($('#edit-name'),'请填写 Case 名称。');$('#edit-name').focus();return;}if(fd.has('objective')&&!objective){validationError($('#edit-objective'),'请描述测试目标。');$('#edit-objective').focus();return;}const tags=String(fd.get('tags')||'').split(/[,，]/).map(x=>x.trim()).filter(Boolean);if(tags.length>6||tags.some(x=>x.length>12)){validationError($('#edit-tags'),'最多 6 个标签，每个不超过 12 个字符。');$('#edit-tags').focus();return;}const values={name,objective,description:String(fd.get('description')||'').trim(),module:String(fd.get('module')||'未分类'),tags:[...new Set(tags)]};if(c){if(!editable(c))return;A.saveCase(values,c.id);closeDialog();if(screen.kind==='list')updateRows();else{renderHeader();renderDefinition();}toast('Case 信息已保存。');}else{const created=A.saveCase({...values,config:A.clone(A.defaults)});newCase={name:'',objective:'',description:'',module:'账号与登录',tags:[]};try{sessionStorage.removeItem('artemis-new-draft');}catch{}closeDialog();go('case/'+created.id);toast('Case 已创建，请在工作区输入测试目标。');}return;}
 if(form.id==='filter-form'){const fd=new FormData(form);list.sort=String(fd.get('sort'));list.controlled=fd.has('controlled');closeDialog();persistList();render();return;}
 if(form.id==='move-form'){const c=A.getCase(form.dataset.id);if(!editable(c))return;c.module=String(new FormData(form).get('module'));c.updated=Date.now();save();closeDialog();render();toast('已移动到'+c.module+'。');}
});
window.addEventListener('hashchange',()=>{rememberView();stopReplay();closeDialog();closeMenu();render();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();return;}if(menuId&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const items=$$('#row-menu button:not(:disabled)'),i=items.indexOf(document.activeElement);items[(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){const search=$('#case-search');if(search){e.preventDefault();search.focus();}}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&document.activeElement.id==='composer-input')$('#composer-form').requestSubmit();});
window.addEventListener('scroll',()=>{if(screen.kind==='list'){list.scroll=window.scrollY;persistList();}closeMenu();},{passive:true});
window.addEventListener('resize',closeMenu);
window.addEventListener('offline',()=>{offline=true;if(['workspace','new'].includes(screen.kind)){const s=viewState(),r=currentRun();if(r&&ongoing(r)){const last=latestFrame(r);s.connected=false;s.lastFrame=last?.frame;s.lastAt=last?.at;r.connectionEvents.push({at:Date.now(),state:'disconnected'});save();}if(getCase()?.pending&&!r)renderMessages();renderRight();}toast('连接中断，保留最后画面。任务状态单独记录。');});
window.addEventListener('online',()=>{offline=false;if(getCase()?.pending&&!currentRun())renderMessages();if(currentRun())renderRight();toast('网络已恢复，可刷新设备或重新连接直播。');});
setInterval(()=>{for(const r of A.data.runs)if(r.status==='running'&&!r.custom){A.advance(r);refreshRun(r);}},3000);
history.scrollRestoration='manual';
A.save();render();
